package com.bitcoinrewards.nfcdisplay;

import org.json.JSONObject;
import java.util.UUID;

final class CheckInApiContract {
    static final int VERSION=2;
    static final int MAX_RESPONSE_BYTES=65536;
    static final class Request { final String url,authorization,body; final boolean followRedirects=false; final int connectTimeoutMs=10000,readTimeoutMs=15000,maxResponseBytes=MAX_RESPONSE_BYTES; Request(String u,String t,JSONObject b){url=u;authorization="Bearer "+t;body=b==null?null:b.toString();} }
    static final class CheckInResponse {final String storeId,deviceId,destination;final long tokenGeneration;final UUID checkInId;final int version;CheckInResponse(String s,String d,long g,String x,UUID c,int v){storeId=s;deviceId=d;tokenGeneration=g;destination=x;checkInId=c;version=v;}PendingOperation correlate(PendingOperation op){if(op.phase!=PendingOperation.Phase.SUBMITTING||!storeId.equals(op.storeId)||!deviceId.equals(op.deviceId)||tokenGeneration!=op.tokenGeneration||!destination.equals(op.destination)||!checkInId.equals(op.checkInId)||version!=op.version)throw bad();return op.submitted();}}
    static final class ConfirmationResponse {final String status,label,resultCode,payoutState;final long amountSatoshis;final PendingOperation operation;ConfirmationResponse(String s,String l,long a,String r,String p,PendingOperation o){status=s;label=l;amountSatoshis=a;resultCode=r;payoutState=p;operation=o;}boolean terminal(){return "PAID".equals(status)||"CANCELLED".equals(status)||"UNPAID".equals(status);}boolean presentConfirmation(){return "AWAITING_CONFIRMATION".equals(status)&&operation.phase==PendingOperation.Phase.AWAITING_APPROVAL;}}

    static Request checkIn(String base,String token,PendingOperation op)throws Exception{if(op.phase!=PendingOperation.Phase.SUBMITTING||op.version!=VERSION)throw bad();JSONObject b=new JSONObject().put("deviceId",op.deviceId).put("tokenGeneration",op.tokenGeneration).put("destination",op.destination).put("checkInId",op.checkInId.toString()).put("protocolVersion",op.version);return new Request(root(base,op.storeId),token,b);}
    static Request pending(String base,String token,PendingOperation op)throws Exception{return new Request(root(base,op.storeId)+"/check-ins/"+segment(op.checkInId.toString())+"?deviceId="+segment(op.deviceId)+"&tokenGeneration="+op.tokenGeneration+"&protocolVersion="+op.version,token,null);}
    static Request confirm(String base,String token,PendingOperation op)throws Exception{if(op.confirmationId==null||op.phase!=PendingOperation.Phase.CONFIRMING)throw bad();return new Request(root(base,op.storeId)+"/confirmations/"+segment(op.confirmationId.toString())+"/confirm",token,correlationBody(op));}
    static Request cancel(String base,String token,PendingOperation op)throws Exception{if(op.confirmationId==null||op.phase!=PendingOperation.Phase.CANCELLING)throw bad();return new Request(root(base,op.storeId)+"/confirmations/"+segment(op.confirmationId.toString())+"/cancel",token,correlationBody(op));}
    private static JSONObject correlationBody(PendingOperation op)throws Exception{return new JSONObject().put("deviceId",op.deviceId).put("tokenGeneration",op.tokenGeneration).put("checkInId",op.checkInId.toString()).put("confirmationId",op.confirmationId.toString()).put("confirmationVersion",op.confirmationVersion).put("protocolVersion",op.version);}
    private static String root(String base,String store)throws Exception{return ApiOrigin.requireConfigured(base)+"/plugins/bitcoin-rewards/"+segment(store)+"/check-in/api/v2";}
    private static String segment(String v){return PathSegmentCodec.encode(v);}

    static CheckInResponse parseCheckInResponse(String raw){JSONObject j=ExactJson.object(raw);PendingOperation.requireKeys(j,"status","storeId","deviceId","tokenGeneration","destination","checkInId","protocolVersion");try{if(!"PENDING".equals(j.getString("status")))throw bad();String s=text(j,"storeId",256),d=text(j,"deviceId",256),x=text(j,"destination",4096);long g=PendingOperation.exactLong(j,"tokenGeneration");int v=PendingOperation.exactInt(j,"protocolVersion");if(g<1||v!=VERSION)throw bad();return new CheckInResponse(s,d,g,x,PendingOperation.exactUuid(j.getString("checkInId")),v);}catch(Exception e){throw bad();}}
    static ConfirmationResponse parseConfirmationResponse(String raw,PendingOperation op){JSONObject j=ExactJson.object(raw);try{String status=j.getString("status");
        if("PENDING".equals(status)){PendingOperation.requireKeys(j,"status","storeId","deviceId","tokenGeneration","destination","checkInId","protocolVersion");correlateBase(j,op);return new ConfirmationResponse(status,"",0,"","",op);}
        if("AWAITING_CONFIRMATION".equals(status)){PendingOperation.requireKeys(j,"status","storeId","deviceId","tokenGeneration","destination","checkInId","confirmationId","confirmationVersion","protocolVersion","amountSatoshis","destinationLabel");correlateBase(j,op);UUID id=PendingOperation.exactUuid(j.getString("confirmationId"));int cv=PendingOperation.exactInt(j,"confirmationVersion");correlateConfirmation(op,id);long amount=PendingOperation.exactLong(j,"amountSatoshis");if(amount<1||amount>2_100_000_000_000_000L)throw bad();String label=text(j,"destinationLabel",256);PendingOperation next=(op.phase==PendingOperation.Phase.CONFIRMING||op.phase==PendingOperation.Phase.CANCELLING)?op.reconciled(id,cv,op.phase):op.awaiting(id,cv);return new ConfirmationResponse(status,label,amount,"","",next);}
        if(isResult(status)){PendingOperation.requireKeys(j,"status","storeId","deviceId","tokenGeneration","destination","checkInId","confirmationId","confirmationVersion","protocolVersion","resultCode","payoutState");correlateBase(j,op);UUID id=PendingOperation.exactUuid(j.getString("confirmationId"));correlateConfirmation(op,id);int cv=PendingOperation.exactInt(j,"confirmationVersion");String result=text(j,"resultCode",100);String payout=j.isNull("payoutState")?null:text(j,"payoutState",64);PendingOperation.Phase requested="CANCELLING".equals(status)?PendingOperation.Phase.CANCELLING:("CONFIRMING".equals(status)?PendingOperation.Phase.CONFIRMING:op.phase);PendingOperation next=op.reconciled(id,cv,requested);return new ConfirmationResponse(status,"",0,result,payout,next);}
        throw bad();}catch(Exception e){throw new IllegalArgumentException("Invalid server response",e);}}
    private static boolean isResult(String s){return "CONFIRMING".equals(s)||"CANCELLING".equals(s)||"PAID".equals(s)||"CANCELLED".equals(s)||"UNPAID".equals(s)||"AMBIGUOUS".equals(s);}
    private static void correlateBase(JSONObject j,PendingOperation op)throws Exception{if(!op.storeId.equals(j.getString("storeId"))||!op.deviceId.equals(j.getString("deviceId"))||op.tokenGeneration!=PendingOperation.exactLong(j,"tokenGeneration")||!op.destination.equals(j.getString("destination"))||!op.checkInId.equals(PendingOperation.exactUuid(j.getString("checkInId")))||op.version!=PendingOperation.exactInt(j,"protocolVersion"))throw bad();}
    private static void correlateConfirmation(PendingOperation op,UUID value){if(op.confirmationId!=null&&!op.confirmationId.equals(value))throw bad();}
    static PendingOperation.Phase reconcilePhase(PendingOperation op,String status,UUID confirmation,int serverVersion){if(op.phase==PendingOperation.Phase.CONFIRMING||op.phase==PendingOperation.Phase.CANCELLING)return op.phase;if("AWAITING_CONFIRMATION".equals(status))return PendingOperation.Phase.AWAITING_APPROVAL;if("CONFIRMING".equals(status))return PendingOperation.Phase.CONFIRMING;if("CANCELLING".equals(status))return PendingOperation.Phase.CANCELLING;return op.phase;}
    static ConfirmationResponse parseConfirmationOrCheckInFixture(String raw,PendingOperation op){JSONObject j=ExactJson.object(raw);if("PENDING".equals(j.optString("status"))&&op.phase==PendingOperation.Phase.SUBMITTING){PendingOperation next=parseCheckInResponse(raw).correlate(op);return new ConfirmationResponse("PENDING","",0,"","",next);}return parseConfirmationResponse(raw,op);}
    static void validateFrozenRequest(String name,JSONObject request,PendingOperation op,UUID confirmation){try{if("check-in".equals(name)){PendingOperation.requireKeys(request,"deviceId","tokenGeneration","destination","checkInId","protocolVersion");}else{PendingOperation.requireKeys(request,"deviceId","tokenGeneration","checkInId","confirmationId","confirmationVersion","protocolVersion");if(!confirmation.equals(PendingOperation.exactUuid(request.getString("confirmationId"))))throw bad();}if(!op.deviceId.equals(request.getString("deviceId"))||op.tokenGeneration!=PendingOperation.exactLong(request,"tokenGeneration")||!op.checkInId.equals(PendingOperation.exactUuid(request.getString("checkInId")))||op.version!=PendingOperation.exactInt(request,"protocolVersion"))throw bad();}catch(Exception e){throw bad();}}
    private static String text(JSONObject j,String k,int max)throws Exception{String s=j.getString(k);PendingOperation.validateText(s,max);return s;}
    private static IllegalArgumentException bad(){return new IllegalArgumentException("Invalid server response");}
}
